# --- Helper Functions ---

def weak_prng(seed, length):
    """
    Simulates a weak PRNG that is improperly seeded.
    In reality, this could be a broken implementation of /dev/urandom,
    a predictable seed source, or a flawed CSPRNG.
    """
    # For demonstration, we use a simple deterministic hash chain.
    # A real weak PRNG might reuse seeds, have low entropy, or be predictable.
    state = seed
    output = b""
    while len(output) < length:
        state = hashlib.sha256(state).digest()
        output += state
    return output[:length]

def predict_ecdsa_nonce_k(curve, message_hash, weak_seed):
    """
    Predicts the ECDSA nonce 'k' generated by a weak PRNG.
    In ECDSA, 'k' must be cryptographically random and unique per signature.
    If 'k' is predictable or reused, the private key can be recovered.
    """
    # Simulate the server's weak PRNG generating 'k'
    # The size of 'k' should match the curve's order size
    k_bytes = weak_prng(weak_seed, 32)  # 256-bit nonce for P-256
    k = int.from_bytes(k_bytes, byteorder='big')
    return k

def recover_private_key_from_reused_k(sig1, sig2, msg_hash1, msg_hash2, curve):
    """
    Recovers the ECDSA private key if the same nonce 'k' is used for two different signatures.
    This is a classic ECDSA nonce reuse attack.
    """
    # ECDSA signature equations:
    # r = (k * G).x mod n
    # s1 = k^-1 * (z1 + d * r) mod n
    # s2 = k^-1 * (z2 + d * r) mod n
    #
    # If k is reused, r is the same for both signatures.
    # We can solve for d (private key):
    # d = (s1 - s2) * (z1 - z2)^-1 * r mod n

    r1, s1 = sig1
    r2, s2 = sig2
    n = curve.order

    # Calculate the difference in s and z
    delta_s = (s1 - s2) % n
    delta_z = (msg_hash1 - msg_hash2) % n

    # Modular inverse of delta_z
    delta_z_inv = pow(delta_z, -1, n)

    # Recover private key d
    d = (delta_s * delta_z_inv * r1) % n
    return d

def craft_ssh_ecdh_key_exchange_init(k_bytes):
    """
    Crafts an SSH ECDH Key Exchange Init message.
    In a real attack, the attacker would observe this message and try to predict
    the ephemeral public key based on the weak PRNG.
    """
    # SSH message format: uint32 length, string data
    msg = struct.pack(">I", len(k_bytes)) + k_bytes
    return msg

def simulate_ssh_ecdsa_sign(message, private_key, curve, weak_seed):
    """
    Simulates an SSH server signing a message with ECDSA using a weak PRNG for 'k'.
    """
    # Generate 'k' using the weak PRNG
    k = predict_ecdsa_nonce_k(curve, message, weak_seed)
    
    # Sign the message
    signer = ecdsa.new(curve, 'der')
    # Note: In a real implementation, the signer would use the weak 'k'.
    # Here we simulate the signature generation for demonstration.
    sig = signer.sign(message, k=k)  # Hypothetical API for demonstration
    return sig

